import aboutStats from "@/data/about-stats.json";
import { ABOUT_AREA_IDS, type AboutAreaId } from "@/lib/about-areas";

export interface AboutStats {
  generatedAt: string;
  organizations: string[];
  publicRepositories: number;
  totalCommits: number;
  commitsByYear: Record<string, number>;
  months: string[];
  commitsByArea: Record<AboutAreaId, number[]>;
  repositoriesByMonth: number[];
  contributors: { login: string; contributions: number }[];
}

/** Generated by `yarn about:data`; imported statically so the server and client render the same numbers. */
export const ABOUT_STATS = aboutStats as AboutStats;

export const CHART_WIDTH = 1280;
export const CHART_HEIGHT = 468;
export const CHART_TOP = 44;
export const CHART_BASE = 408;

const TARGET_GRIDLINES = 4;

export interface ChartBand {
  id: AboutAreaId;
  path: string;
}

export interface GrowthChart {
  bands: ChartBand[];
  /** Top edge of every band but the last, drawn in the page background to separate the fills. */
  separators: ChartBand[];
  gridlines: { value: number; y: number }[];
  years: { year: number; x: number; commits: number }[];
  /** x of every year boundary, including the right edge. */
  yearLines: number[];
  months: { month: string; x: number; width: number; total: number }[];
  latest: { x: number; y: number };
  scaleY: (value: number) => number;
}

function round(value: number) {
  return Math.round(value * 10) / 10;
}

function parseMonth(month: string) {
  const [year, monthNumber] = month.split("-").map(Number);
  return { year, monthIndex: monthNumber - 1 };
}

function niceStep(raw: number) {
  const power = 10 ** Math.floor(Math.log10(raw));
  const fraction = raw / power;
  const nice =
    fraction < 1.5 ? 1 : fraction < 2.25 ? 2 : fraction < 3.5 ? 2.5 : fraction < 7.5 ? 5 : 10;
  return nice * power;
}

// Monotone cubic tangents (in value per month) keep each series inside its neighbors' range,
// so summed curves never cross and every band boundary stays ordered.
function monotoneTangents(values: number[]) {
  return values.map((_, index) => {
    if (index === 0 || index === values.length - 1) return 0;
    const before = values[index] - values[index - 1];
    const after = values[index + 1] - values[index];
    if (before * after <= 0) return 0;
    return (
      Math.sign(before) *
      2 *
      Math.min(Math.abs(before), Math.abs(after), Math.abs(before + after) / 4)
    );
  });
}

export function buildGrowthChart(stats: AboutStats): GrowthChart {
  const { months } = stats;
  const count = months.length;
  const first = parseMonth(months[0]);
  const lastYear = parseMonth(months[count - 1]).year;
  const yearCount = lastYear - first.year + 1;
  // The x axis runs to the end of the current year so each year gets the same width.
  const slot = CHART_WIDTH / (yearCount * 12);
  const offset = first.monthIndex;
  const centerX = (index: number) => (offset + index + 0.5) * slot;
  const startX = offset * slot;
  const endX = (offset + count) * slot;

  const cumulativeValues: number[][] = [];
  const cumulativeTangents: number[][] = [];
  ABOUT_AREA_IDS.forEach((id, areaIndex) => {
    const values = stats.commitsByArea[id];
    const tangents = monotoneTangents(values);
    cumulativeValues.push(
      values.map(
        (value, index) => (areaIndex ? cumulativeValues[areaIndex - 1][index] : 0) + value,
      ),
    );
    cumulativeTangents.push(
      tangents.map(
        (value, index) => (areaIndex ? cumulativeTangents[areaIndex - 1][index] : 0) + value,
      ),
    );
  });
  const totals = cumulativeValues[cumulativeValues.length - 1];

  const maxTotal = Math.max(...totals, 1);
  const step = niceStep(maxTotal / TARGET_GRIDLINES);
  const gridCount = Math.max(1, Math.floor(maxTotal / step));
  // Headroom above the tallest month leaves room for the annotations.
  const yMax = Math.max(maxTotal, gridCount * step) * 1.08;
  const scaleY = (value: number) => CHART_BASE - (value * (CHART_BASE - CHART_TOP)) / yMax;
  const point = (x: number, value: number) => `${round(x)},${round(scaleY(value))}`;

  const forward = (values: number[], tangents: number[]) => {
    let path = `L${point(centerX(0), values[0])}`;
    for (let index = 0; index < count - 1; index++) {
      path +=
        `C${point(centerX(index) + slot / 3, values[index] + tangents[index] / 3)} ` +
        `${point(centerX(index + 1) - slot / 3, values[index + 1] - tangents[index + 1] / 3)} ` +
        point(centerX(index + 1), values[index + 1]);
    }
    return `${path}L${point(endX, values[count - 1])}`;
  };
  const backward = (values: number[], tangents: number[]) => {
    let path = `L${point(endX, values[count - 1])}L${point(centerX(count - 1), values[count - 1])}`;
    for (let index = count - 1; index > 0; index--) {
      path +=
        `C${point(centerX(index) - slot / 3, values[index] - tangents[index] / 3)} ` +
        `${point(centerX(index - 1) + slot / 3, values[index - 1] + tangents[index - 1] / 3)} ` +
        point(centerX(index - 1), values[index - 1]);
    }
    return `${path}L${point(startX, values[0])}`;
  };
  const topEdge = (areaIndex: number) =>
    `M${point(startX, cumulativeValues[areaIndex][0])}${forward(
      cumulativeValues[areaIndex],
      cumulativeTangents[areaIndex],
    )}`;

  const bands = ABOUT_AREA_IDS.map((id, areaIndex) => ({
    id,
    path: `${topEdge(areaIndex)}${
      areaIndex
        ? backward(cumulativeValues[areaIndex - 1], cumulativeTangents[areaIndex - 1])
        : `L${point(endX, 0)}L${point(startX, 0)}`
    }Z`,
  }));
  const separators = ABOUT_AREA_IDS.slice(0, -1).map((id, areaIndex) => ({
    id,
    path: topEdge(areaIndex),
  }));

  const years = Array.from({ length: yearCount }, (_, index) => {
    const year = first.year + index;
    return { year, x: round(index * 12 * slot), commits: stats.commitsByYear[String(year)] ?? 0 };
  });

  return {
    bands,
    separators,
    gridlines: Array.from({ length: gridCount }, (_, index) => {
      const value = (index + 1) * step;
      return { value, y: Math.round(scaleY(value)) + 0.5 };
    }),
    years,
    yearLines: [...years.map((year) => year.x), CHART_WIDTH],
    months: months.map((month, index) => ({
      month,
      x: round((offset + index) * slot),
      width: round(slot),
      total: totals[index],
    })),
    latest: { x: round(centerX(count - 1)), y: round(scaleY(totals[count - 1])) },
    scaleY,
  };
}

/** Repository counts at the end of last year and now, when the data reaches back that far. */
export function getRepositoryGrowth(stats: AboutStats) {
  const currentYear = Number(stats.generatedAt.slice(0, 4));
  const endOfLastYear = stats.months.indexOf(`${currentYear - 1}-12`);
  if (endOfLastYear === -1) return null;

  const before = stats.repositoriesByMonth[endOfLastYear];
  const now = stats.repositoriesByMonth[stats.repositoriesByMonth.length - 1];
  return { before, now, started: now - before, lastYear: currentYear - 1, currentYear };
}

export function sumAreaCommits(stats: AboutStats, id: AboutAreaId, year?: string) {
  return stats.commitsByArea[id].reduce(
    (sum, value, index) => (!year || stats.months[index].startsWith(year) ? sum + value : sum),
    0,
  );
}
